hooks.command:
jq -r '.tool_input.file_path // .tool_response.filePath' | { read -r f; case "$f" in *.html) python3 -c "
import sys
text = open(sys.argv[1]).read()
problems = []
if not text.rstrip().endswith('</html>'): problems.append('file does not end with </html> (truncated?)')
for tag in ('script', 'style', 'body', 'head'):
    opens = text.count('<' + tag + '>') + text.count('<' + tag + ' ')
    closes = text.count('</' + tag + '>')
    if opens != closes: problems.append('unbalanced <' + tag + '> tags (%d open, %d close)' % (opens, closes))
if problems:
    print('HTML CHECK FAILED: ' + '; '.join(problems)); sys.exit(2)
" "$f";; esac; }
